15	/**
16	 * Scans configured paths into per-directory listings in one filesystem pass.
17	 *
18	 * Excluded files are dropped from their listing and excluded directories are
19	 * pruned together with their whole subtree.
20	 */
21	final class DirectoryTreeScanner
22	{
23	    /** @readonly */
24	    private TreeGuardPathResolver $pathResolver;
25	
