32	    /**
33	     * Creates a scanner from path resolution, exclusion, and per-directory reading.
34	     */
35	    public function __construct(
36	        ?TreeGuardPathResolver $pathResolver = null,
37	        ?PathInclusionPolicy $inclusionPolicy = null,
38	        ?DirectoryListingReader $listingReader = null,
39	    ) {
40	        $this->pathResolver = $pathResolver ?? new TreeGuardPathResolver();
41	        $this->inclusionPolicy = $inclusionPolicy ?? new PathInclusionPolicy();
42	        $this->listingReader = $listingReader ?? new DirectoryListingReader();
43	    }
44	
45	    /**
46	     * Returns listings for every scanned directory, keyed and sorted by relative path.
47	     *
48	     * @return array<string, DirectoryListing>
49	     *
50	     * @throws TreeGuardException when a configured path is not a readable directory
51	     */
52	    public function scan(TreeGuardConfig $config): array
53	    {
54	        $listings = [];
55	        foreach ($config->paths as $path) {
56	            $absolutePath = $this->pathResolver->absolute($config->root, $path);
57	            if (!is_dir($absolutePath)) {
58	                throw new TreeGuardException(sprintf('Configured path is not a directory: %s', $path));
59	            }
60	
61	            $queue = [[$absolutePath, $this->pathResolver->relative($config->root, $absolutePath)]];
62	            for ($index = 0; $index < count($queue); $index++) {
63	                [$absoluteDir, $relativeDir] = $queue[$index];
64	                $entries = $this->listingReader->read($absoluteDir);
65	                $fileNames = [];
66	                foreach ($entries['files'] as $name) {
67	                    if ($this->inclusionPolicy->includes($config, $this->pathResolver->child($relativeDir, $name))) {
68	                        $fileNames[] = $name;
69	                    }
70	                }
71	                $dirNames = [];
72	                foreach ($entries['dirs'] as $name) {
73	                    $childPath = $this->pathResolver->child($relativeDir, $name);
74	                    if ($this->inclusionPolicy->includes($config, $childPath)) {
75	                        $dirNames[] = $name;
76	                        $queue[] = [$absoluteDir . '/' . $name, $childPath];
77	                    }
78	                }
79	                $listings[$relativeDir] = new DirectoryListing($relativeDir, $fileNames, $dirNames);
80	            }
81	        }
82	
83	        ksort($listings);
84	
